<script setup>
import { computed, inject, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import RefreshIcon from './RefreshIcon.vue'
import DirectoryTree from './DirectoryTree.vue'
import RegisterWizard from './components/dataobject/RegisterWizard.vue'
import ObjectEditor from './components/dataobject/ObjectEditor.vue'
import SchemaEditor from './components/dataobject/SchemaEditor.vue'
import { objectRequest, objectWrite } from './data-object-api.js'
const can=inject('canPermission',()=>false),directories=ref([]),sources=ref([]),rows=ref([]),total=ref(0),page=ref(1),size=ref(10),selected=ref(0),table=ref(''),name=ref(''),filters=ref({table:'',name:''}),error=ref(''),registerOpen=ref(false),createOpen=ref(false),detail=ref(null),detailOpen=ref(false),edit=ref(false),editForm=ref({}),loading=ref(false),pending=ref([]),pendingOpen=ref(false)
const options=computed(()=>{const build=(parent,depth)=>directories.value.filter(d=>d.parentId===parent).flatMap(d=>[{id:d.id,label:'　'.repeat(depth)+d.name},...build(d.id,depth+1)]);return build(null,0)})
const sourceName=id=>id==null?'—':sources.value.find(s=>s.id===id)?.name||`数据源 ${id}`
const schemaOpen=ref(false), schemaObject=ref(null), copyFrom=ref(null), previewOpen=ref(false), previewObject=ref(null), previewRows=ref([]), previewTotal=ref(0), previewPage=ref(1), previewSize=ref(20), previewLoading=ref(false), previewFilters=ref([{field:'',operator:'CONTAINS',value:''}]), schemaPending=ref([]), actualFields=ref([]), actualOperation=ref(null), actualOpen=ref(false)
const treeRevision=ref(0)
async function sortDirectories(items){try{await objectWrite('/api/object-directories/sort','POST',{items});await load()}catch(e){await load();error.value=e.message}finally{treeRevision.value++}}
function selectDirectory(id){selected.value=id;page.value=1;loadPage()}
let sequence=0
async function loadPage(){const seq=++sequence;try{const q=new URLSearchParams({table:filters.value.table,name:filters.value.name,page:String(page.value),size:String(size.value)});if(selected.value)q.set('directoryId',String(selected.value));const result=await objectRequest(`/api/data-objects?${q}`);if(seq!==sequence)return;if(page.value>1&&!result.rows.length&&result.total){page.value=Math.ceil(result.total/size.value);return loadPage()}rows.value=result.rows;total.value=result.total}catch(e){if(seq===sequence)error.value=e.message}}
async function load(){try{error.value='';const [dirs,src]=await Promise.all([can('datasource.object_directory.read')?objectRequest('/api/object-directories'):Promise.resolve([]),can('datasource.source.read')?objectRequest('/api/data-sources'):Promise.resolve([])]);directories.value=dirs;sources.value=src;if(can('datasource.object.read'))await loadPage()}catch(e){error.value=e.message}}
function query(){filters.value={table:table.value.trim(),name:name.value.trim()};page.value=1;void loadPage()}
async function directoryAction(command,node){try{if(command==='add'){const r=await ElMessageBox.prompt('输入目录名称','新增目录',{inputPattern:/\S/,inputErrorMessage:'请输入目录名称'});await objectWrite('/api/object-directories','POST',{name:r.value,parentId:node.id||null})}else if(command==='rename'){const r=await ElMessageBox.prompt('输入目录名称','重命名目录',{inputValue:node.name,inputPattern:/\S/});await objectWrite(`/api/object-directories/${node.id}`,'PUT',{name:r.value})}else{await ElMessageBox.confirm(`确定删除目录「${node.name}」？`,'删除目录',{type:'warning'});await objectWrite(`/api/object-directories/${node.id}`,'DELETE');if(selected.value===node.id)selected.value=0}await load();ElMessage.success('操作成功')}catch(e){if(e instanceof Error)error.value=e.message}}
async function show(row,editing=false){try{detail.value=await objectRequest(`/api/data-objects/${row.id}`);edit.value=editing;editForm.value={directoryId:row.directoryId,name:row.name,description:row.description,version:row.version};detailOpen.value=true}catch(e){error.value=e.message}}
async function structure(row){try{schemaObject.value=await objectRequest(`/api/data-objects/${row.id}`);schemaOpen.value=true}catch(e){error.value=e.message}}
async function copy(row){try{copyFrom.value=await objectRequest(`/api/data-objects/${row.id}`);createOpen.value=true}catch(e){error.value=e.message}}
async function previewData(row){try{previewObject.value=await objectRequest(`/api/data-objects/${row.id}`);previewPage.value=1;previewFilters.value=[{field:'',operator:'CONTAINS',value:''}];previewOpen.value=true;await loadPreview()}catch(e){ElMessage.error(e.message)}}
const previewFilterOperators=[{label:'包含',value:'CONTAINS',text:true},{label:'开头为',value:'STARTS_WITH',text:true},{label:'等于',value:'EQ'},{label:'不等于',value:'NE'},{label:'大于',value:'GT'},{label:'大于等于',value:'GTE'},{label:'小于',value:'LT'},{label:'小于等于',value:'LTE'},{label:'为空',value:'IS_NULL',noValue:true},{label:'不为空',value:'NOT_NULL',noValue:true}]
function previewOperatorsFor(filter){const field=previewObject.value?.fields?.find(item=>item.name===filter.field);const text=field&&[1,12,-1,-9,-10,-16,2005,2011].includes(field.jdbcType);return previewFilterOperators.filter(operator=>!operator.text||!filter.field||text)}
function previewChooseField(filter,field){filter.field=field;if(!previewOperatorsFor(filter).some(item=>item.value===filter.operator))filter.operator='EQ'}
function previewActiveFilters(){return previewFilters.value.filter(item=>item.field&&(['IS_NULL','NOT_NULL'].includes(item.operator)||String(item.value??'').trim()!=='')).map(item=>({field:item.field,operator:item.operator,value:item.value===''?null:item.value}))}
async function loadPreview(){if(!previewObject.value)return;previewLoading.value=true;try{const detail=previewObject.value;const q=new URLSearchParams({page:String(previewPage.value),size:String(previewSize.value)});const active=previewActiveFilters();if(active.length)q.set('filters',JSON.stringify(active));const result=await objectRequest(`/api/data-objects/${detail.object.id}/preview?${q}`);previewRows.value=result.rows||[];previewTotal.value=result.total||0}catch(e){ElMessage.error(e.message)}finally{previewLoading.value=false}}
function previewQuery(){previewPage.value=1;void loadPreview()}
function previewAddFilter(){previewFilters.value.push({field:'',operator:'EQ',value:''})}
function previewRemoveFilter(index){previewFilters.value.splice(index,1);if(!previewFilters.value.length)previewAddFilter()}
async function save(){try{loading.value=true;await objectWrite(`/api/data-objects/${detail.value.object.id}`,'PUT',editForm.value);detailOpen.value=false;await load();ElMessage.success('已保存对象资料')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`确定删除「${row.name}」的对象登记？数据库中的表和数据会保留。`,'删除对象登记',{type:'warning'});await objectWrite(`/api/data-objects/${row.id}`,'DELETE');await load();ElMessage.success('对象登记已删除')}catch(e){if(e instanceof Error)error.value=e.message}}
const operationStatuses={PREPARED:['待执行','预览已保存，可取消预览。'],EXECUTING:['执行中','执行中或执行已中断；请核对实际状态。'],UNKNOWN:['结果待核对','执行结果不确定，请核对目标数据库。'],NEEDS_REGISTRATION:['待重新登记','物理表可能已创建，请核对后重新登记。'],PARTIAL:['部分完成','部分变更可能已执行，请核对实际结构。']}
function operationStatus(status){return operationStatuses[status]?.[0]||status}
function operationHint(row){return row.error||operationStatuses[row.status]?.[1]||'请检查操作状态。'}
function operationTarget(identity){return [identity?.catalog,identity?.schema,identity?.table].filter(Boolean).join(' / ')||'—'}
function operationTime(value){return value?String(value).replace('T',' ').slice(0,19):'—'}
async function operations(){try{pending.value=can('datasource.object.create_table')?await objectRequest('/api/data-object-operations'):[];schemaPending.value=can('datasource.object.publish_schema')?await objectRequest('/api/data-object-schema-operations'):[];pendingOpen.value=true}catch(e){error.value=e.message}}
async function inspectSchema(item){try{actualFields.value=await objectRequest(`/api/data-object-schema-operations/${item.operationId}/actual`);actualOperation.value=item;actualOpen.value=true}catch(e){ElMessage.error(e.message)}}
async function acknowledgeSchema(){try{await ElMessageBox.confirm('确认已核对以上实际字段？平台将以当前物理结构更新快照，并允许重新编辑。','确认实际结构',{type:'warning'});await objectWrite(`/api/data-object-schema-operations/${actualOperation.value.operationId}/acknowledge`,'POST',{});actualOpen.value=false;await operations();await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
async function cancelSchema(item){try{await objectWrite(`/api/data-object-schema-operations/${item.operationId}`,'DELETE');await operations()}catch(e){ElMessage.error(e.message)}}
async function recover(item){try{loading.value=true;await objectWrite(`/api/data-object-operations/${item.operationId}/recover`,'POST',{});await operations();await load();ElMessage.success('已重新登记')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
async function resolveAbsent(item){try{await ElMessageBox.confirm('系统将检查目标数据库，只有目标表不存在时才解除待处理状态，不会重新建表。','核对目标表',{type:'warning'});await objectWrite(`/api/data-object-operations/${item.operationId}/resolve-absent`,'POST',{});await operations();ElMessage.success('已确认目标表不存在')}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
async function cancel(item){try{await objectWrite(`/api/data-object-operations/${item.operationId}`,'DELETE');await operations();ElMessage.success('预览已取消')}catch(e){ElMessage.error(e.message)}}
function exportData(){const q=new URLSearchParams({table:filters.value.table,name:filters.value.name});if(selected.value)q.set('directoryId',String(selected.value));window.location.href=`/api/data-objects/export?${q}`}
onMounted(load)
</script>
<template><section class="objects-page"><el-alert v-if="error" :title="error" type="error" show-icon closable @close="error=''"/><div class="layout"><DirectoryTree :key="treeRevision" :directories="directories" root-label="数据对象目录" :selected="selected" :can-create="can('datasource.object_directory.create')" :can-update="can('datasource.object_directory.update')" :can-delete="can('datasource.object_directory.delete')" @select="selectDirectory" @action="directoryAction" @sort="sortDirectories"/><div class="main"><div class="toolbar list-query-toolbar"><div class="list-query-controls"><el-input v-model="table" placeholder="对象表名" clearable @keyup.enter="query"/><el-input v-model="name" placeholder="对象中文名" clearable @keyup.enter="query"/><el-button type="primary" @click="query">查询</el-button></div><div class="list-query-actions"><el-button v-if="can('datasource.object.create_table')" type="primary" @click="copyFrom=null;createOpen=true">新增</el-button><el-button v-if="can('datasource.object.register')" @click="registerOpen=true">注册</el-button><el-button v-if="can('datasource.object.export')" @click="exportData">导出</el-button><el-button v-if="can('datasource.object.create_table')||can('datasource.object.publish_schema')" @click="operations">待处理操作</el-button><el-button class="refresh-button" title="刷新" aria-label="刷新" @click="load"><RefreshIcon/></el-button></div></div><div class="list"><el-table :data="rows" height="100%" empty-text="暂无数据对象"><el-table-column type="index" label="序号" width="70" :index="index=>(page-1)*size+index+1"/><el-table-column label="对象名称" min-width="150"><template #default="s">{{ s.row.identity.table }}</template></el-table-column><el-table-column prop="name" label="对象中文名" min-width="150"/><el-table-column label="数据源" min-width="130"><template #default="s">{{ sourceName(s.row.identity?.sourceId) }}</template></el-table-column><el-table-column label="对象目录" min-width="100"><template #default="s">{{directories.find(d=>d.id===s.row.directoryId)?.name||'—'}}</template></el-table-column><el-table-column prop="updatedAt" label="更新时间" min-width="160"/><el-table-column label="模式" min-width="100"><template #default="s">{{ s.row.identity.schema || s.row.identity.catalog || '—' }}</template></el-table-column><el-table-column label="操作" fixed="right" min-width="180"><template #default="s"><el-button v-if="can('datasource.object.preview')" link type="primary" @click="previewData(s.row)">预览</el-button><el-button link type="primary" @click="show(s.row)">查看</el-button><el-button v-if="s.row.identity.type==='TABLE'&&can('datasource.object.publish_schema')" link type="primary" @click="structure(s.row)">字段</el-button><el-button v-if="can('datasource.object.create_table')" link type="primary" @click="copy(s.row)">复制</el-button><el-button v-if="can('datasource.object.update')" link type="primary" @click="show(s.row,true)">编辑</el-button><el-button v-if="can('datasource.object.delete')" link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @current-change="loadPage" @size-change="page=1;loadPage()"/></div></div></div>
<RegisterWizard v-model="registerOpen" :sources="sources" :directories="options" :selected-directory="selected" @registered="load"/><ObjectEditor v-model="createOpen" :sources="sources" :directories="options" :selected-directory="selected" :copy-from="copyFrom" @created="load"/><SchemaEditor v-model="schemaOpen" :object="schemaObject" :source="sources.find(s=>s.id===schemaObject?.object.identity.sourceId)" @published="load"/><el-dialog v-model="previewOpen" :title="`数据预览 · ${previewObject?.object?.identity?.table||''}`" width="min(1200px,96vw)" destroy-on-close>
  <div class="preview-panel">
    <div class="preview-heading" v-if="previewObject">
      <div class="preview-object-title">
        <h2>{{ previewObject.object.name||previewObject.object.identity.table }}</h2>
        <span class="preview-physical">{{ previewObject.object.identity.table }}</span>
      </div>
      <div class="preview-context">
        <span>{{ sourceName(previewObject.object.identity?.sourceId) }}</span><i></i>
        <span>{{ previewObject.object.identity.catalog||previewObject.object.identity.schema||'默认数据库' }}</span><i></i>
        <span>{{ previewObject.object.identity.type==='VIEW'?'视图':'数据表' }}</span>
      </div>
    </div>
    <div class="preview-toolbar toolbar list-query-toolbar">
      <div class="list-query-controls filters">
        <div v-for="(filter,index) in previewFilters" :key="index" class="filter-row">
          <el-select :model-value="filter.field" placeholder="字段" aria-label="筛选字段" @change="previewChooseField(filter,$event)">
            <el-option v-for="field in previewObject?.fields" :key="field.name" :label="field.remarks?`${field.remarks}（${field.name}）`:field.name" :value="field.name"/>
          </el-select>
          <el-select v-model="filter.operator" placeholder="条件" aria-label="筛选方式">
            <el-option v-for="operator in previewOperatorsFor(filter)" :key="operator.value" :label="operator.label" :value="operator.value"/>
          </el-select>
          <el-input v-if="!['IS_NULL','NOT_NULL'].includes(filter.operator)" v-model="filter.value" clearable placeholder="筛选内容" aria-label="筛选内容" @keyup.enter="previewQuery"/>
          <el-button v-if="previewFilters.length>1" text type="danger" aria-label="删除筛选条件" @click="previewRemoveFilter(index)">移除</el-button>
        </div>
        <el-button class="add-filter" text @click="previewAddFilter">＋ 条件</el-button>
        <el-button type="primary" @click="previewQuery">查询</el-button>
      </div>
      <div class="list-query-actions">
        <el-button class="refresh-button" aria-label="刷新" title="刷新" :loading="previewLoading" @click="loadPreview">
          <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M16.1 7.1A6.5 6.5 0 0 0 4.6 5.8L3.2 7.4M3.2 7.4V3.9m0 3.5h3.5M3.9 12.9a6.5 6.5 0 0 0 11.5 1.3l1.4-1.6m0 0v3.5m0-3.5h-3.5"/></svg>
        </el-button>
      </div>
    </div>
    <el-table v-loading="previewLoading" class="preview-table" :data="previewRows" height="100%" empty-text="暂无数据">
      <el-table-column v-for="field in previewObject?.fields" :key="field.name" :prop="field.name" :min-width="field.remarks?.length>10?180:150" show-overflow-tooltip>
        <template #header><el-tooltip :content="field.name + ' · ' + field.type + (field.remarks ? ' · ' + field.remarks : '')"><span>{{ field.remarks||field.name }}</span></el-tooltip></template>
        <template #default="scope"><span>{{ scope.row[field.name]===null||scope.row[field.name]===undefined?'NULL':String(scope.row[field.name]) }}</span></template>
      </el-table-column>
    </el-table>
    <div class="preview-footer">
      <span>共 {{ previewTotal }} 条</span>
      <el-pagination v-model:current-page="previewPage" v-model:page-size="previewSize" :page-sizes="[20,50,100]" :total="previewTotal" layout="sizes, prev, pager, next" @size-change="previewQuery" @current-change="loadPreview"/>
    </div>
  </div>
</el-dialog>
<el-dialog v-model="detailOpen" :title="edit?'编辑对象资料':'查看数据对象'" width="min(850px,96vw)"><template v-if="detail"><el-form label-position="top"><div class="form-grid"><el-form-item label="对象名称"><el-input :model-value="detail.object.identity.table" disabled/></el-form-item><el-form-item label="对象中文名"><el-input v-model="editForm.name" :disabled="!edit" maxlength="200"/></el-form-item><el-form-item label="对象目录"><el-select v-model="editForm.directoryId" :disabled="!edit"><el-option v-for="d in options" :key="d.id" :label="d.label" :value="d.id"/></el-select></el-form-item><el-form-item label="描述"><el-input v-model="editForm.description" :disabled="!edit" maxlength="1000"/></el-form-item></div></el-form><el-table :data="detail.fields" max-height="350"><el-table-column prop="name" label="字段名"/><el-table-column prop="type" label="原始类型"/><el-table-column prop="length" label="长度"/><el-table-column prop="scale" label="精度"/><el-table-column prop="nullable" label="可空"/><el-table-column prop="primaryKey" label="主键"/><el-table-column prop="remarks" label="注释"/></el-table></template><template #footer><el-button @click="detailOpen=false">关闭</el-button><el-button v-if="edit" type="primary" :loading="loading" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="pendingOpen" title="待处理操作" width="min(1100px,96vw)">
  <p class="pending-intro">这里显示尚未完成或需要核对的建表和字段结构操作。已完成的操作不在此列表中。</p>
  <h4 class="pending-heading">建表操作 <span>{{ pending.length }}</span></h4>
  <el-table :data="pending" empty-text="暂无待处理的建表操作" max-height="280">
    <el-table-column label="目标对象" min-width="170" show-overflow-tooltip><template #default="s"><div>{{ s.row.name || s.row.identity?.table || (s.row.objectId ? `对象 ${s.row.objectId}` : '—') }}</div><small class="pending-secondary">{{ operationTarget(s.row.identity) }}</small></template></el-table-column>
    <el-table-column label="数据源" min-width="110" show-overflow-tooltip><template #default="s">{{ sourceName(s.row.identity?.sourceId) }}</template></el-table-column>
    <el-table-column label="状态与处理提示" min-width="230"><template #default="s"><el-tag size="small" :type="s.row.status==='PREPARED'?'info':'warning'">{{ operationStatus(s.row.status) }}</el-tag><div class="pending-hint">{{ operationHint(s.row) }}</div></template></el-table-column>
    <el-table-column label="创建时间" min-width="150"><template #default="s">{{ operationTime(s.row.createdAt) }}</template></el-table-column>
    <el-table-column label="操作" min-width="180"><template #default="s"><el-button v-if="s.row.status==='PREPARED'" link type="primary" @click="cancel(s.row)">取消预览</el-button><template v-else-if="['EXECUTING','UNKNOWN','NEEDS_REGISTRATION'].includes(s.row.status)"><el-button v-if="can('datasource.object.register')" link type="primary" :loading="loading" @click="recover(s.row)">核对并重新登记</el-button><el-button link type="primary" @click="resolveAbsent(s.row)">核对表不存在</el-button></template></template></el-table-column>
  </el-table>
  <h4 class="pending-heading">字段结构发布 <span>{{ schemaPending.length }}</span></h4>
  <el-table :data="schemaPending" empty-text="暂无待处理的结构发布操作" max-height="280">
    <el-table-column label="目标对象" min-width="170" show-overflow-tooltip><template #default="s"><div>{{ s.row.name || s.row.identity?.table || (s.row.objectId ? `对象 ${s.row.objectId}` : '—') }}</div><small class="pending-secondary">{{ operationTarget(s.row.identity) }}</small></template></el-table-column>
    <el-table-column label="数据源" min-width="110" show-overflow-tooltip><template #default="s">{{ sourceName(s.row.identity?.sourceId) }}</template></el-table-column>
    <el-table-column label="状态与处理提示" min-width="230"><template #default="s"><el-tag size="small" :type="s.row.status==='PREPARED'?'info':'warning'">{{ operationStatus(s.row.status) }}</el-tag><div class="pending-hint">{{ operationHint(s.row) }}</div></template></el-table-column>
    <el-table-column label="创建时间" min-width="150"><template #default="s">{{ operationTime(s.row.createdAt) }}</template></el-table-column>
    <el-table-column label="操作" min-width="120"><template #default="s"><el-button v-if="s.row.status==='PREPARED'" link type="primary" @click="cancelSchema(s.row)">取消预览</el-button><el-button v-if="['EXECUTING','UNKNOWN','PARTIAL'].includes(s.row.status)" link type="primary" @click="inspectSchema(s.row)">核对实际结构</el-button></template></el-table-column>
  </el-table>
</el-dialog><el-dialog v-model="actualOpen" title="核对物理表当前结构" width="min(900px,96vw)"><el-alert title="请核对数据库中的实际字段；确认后平台将同步快照，不会再次执行 SQL。" type="warning" :closable="false"/><el-table :data="actualFields"><el-table-column prop="name" label="字段"/><el-table-column prop="type" label="类型"/><el-table-column prop="length" label="长度"/><el-table-column prop="nullable" label="可空"/><el-table-column prop="primaryKey" label="主键"/></el-table><template #footer><el-button @click="actualOpen=false">关闭</el-button><el-button type="primary" @click="acknowledgeSchema">确认实际结构</el-button></template></el-dialog></section></template>
